from __future__ import annotations

"""Per-contact conversation state built from a stream of messages.

The store is fed messages as they happen (or replayed from history) and keeps a
small summary per contact: when the conversation started, the most recent
activity, and counts. Other parts of the system read this summary instead of
walking the whole message log every time they need to make a decision.

State is held in memory and keyed by the contact's ``wa_id``. Feeding the same
history twice should land on the same place, so updates take the later of the
stored value and the incoming one rather than blindly overwriting.
"""

from dataclasses import dataclass, field
from datetime import datetime
from typing import Dict, Iterable, Optional

from message_models import Contact, Direction, Message


@dataclass
class ContactState:
    """What the store remembers about one contact's conversation."""

    contact: Contact
    started_at: datetime
    last_activity_at: datetime
    last_inbound_at: Optional[datetime] = None
    last_outbound_at: Optional[datetime] = None
    inbound_count: int = 0
    outbound_count: int = 0

    def touch(self, message: Message) -> None:
        """Fold a new message for this contact into the running summary."""

        ts = message.timestamp
        # Most recent activity of any kind on the thread.
        if ts > self.last_activity_at:
            self.last_activity_at = ts

        if message.direction == Direction.INBOUND:
            self.inbound_count += 1
            if self.last_inbound_at is None or ts > self.last_inbound_at:
                self.last_inbound_at = ts
        else:
            self.outbound_count += 1
            if self.last_outbound_at is None or ts > self.last_outbound_at:
                self.last_outbound_at = ts


class ConversationStore:
    """Holds :class:`ContactState` for every contact the business has seen."""

    def __init__(self) -> None:
        self._by_wa_id: Dict[str, ContactState] = {}

    def record(self, message: Message) -> ContactState:
        """Record one message and return the updated state for its contact."""

        wa_id = message.wa_id
        state = self._by_wa_id.get(wa_id)
        if state is None:
            state = ContactState(
                contact=message.contact,
                started_at=message.timestamp,
                last_activity_at=message.timestamp,
            )
            self._by_wa_id[wa_id] = state
        else:
            if message.timestamp < state.started_at:
                state.started_at = message.timestamp
        state.touch(message)
        return state

    def record_all(self, messages: Iterable[Message]) -> None:
        """Replay a batch of messages in the order given."""

        for message in messages:
            self.record(message)

    def get(self, wa_id: str) -> Optional[ContactState]:
        return self._by_wa_id.get(wa_id)

    def state_for(self, contact: Contact) -> Optional[ContactState]:
        return self._by_wa_id.get(contact.wa_id)

    def has_contact(self, wa_id: str) -> bool:
        return wa_id in self._by_wa_id

    def contacts(self) -> Iterable[str]:
        return tuple(self._by_wa_id.keys())

    def reset(self) -> None:
        self._by_wa_id.clear()

    def last_customer_reference(self, wa_id: str) -> Optional[datetime]:
        """The timestamp that should anchor the customer-service window.

        The window is measured from the customer's side of the conversation.
        When a contact is unknown there is nothing to anchor on.
        """

        state = self._by_wa_id.get(wa_id)
        if state is None:
            return None
        return state.last_activity_at

    def reference_for(self, contact: Contact) -> Optional[datetime]:
        return self.last_customer_reference(contact.wa_id)


def build_store(messages: Iterable[Message]) -> ConversationStore:
    """Convenience constructor: a fresh store with ``messages`` replayed in."""

    store = ConversationStore()
    store.record_all(messages)
    return store

