from __future__ import annotations

"""Decides how a reply may be delivered and hands it to the transport.

This is the layer an agent UI or an automation calls when it wants to reply to a
contact. It reads the conversation state to find the window anchor, asks the
window policy whether a free-form message is allowed right now, and either:

- sends the free-form reply, or
- falls back to an approved template when the window has closed.

If a free-form reply is requested but the window is closed and no template is
available, the send is rejected rather than sent (the API would reject it).
"""

from dataclasses import dataclass, field
from datetime import datetime
from enum import Enum
from typing import List, Optional

from conversation_state import ConversationStore
from message_models import (
    Contact,
    IntendedReply,
    Message,
    MessageKind,
    outbound,
)
from window_policy import WindowStatus, evaluate_window


class Decision(str, Enum):
    """What the sender decided to do with an intended reply."""

    SENT_FREE_FORM = "sent_free_form"
    SENT_TEMPLATE = "sent_template"
    REJECTED = "rejected"


@dataclass
class SendResult:
    """Outcome of an attempt to reply to a contact."""

    decision: Decision
    contact: Contact
    window: WindowStatus
    message: Optional[Message] = None
    reason: str = ""

    @property
    def sent(self) -> bool:
        return self.decision in (Decision.SENT_FREE_FORM, Decision.SENT_TEMPLATE)

    @property
    def used_template(self) -> bool:
        return self.decision == Decision.SENT_TEMPLATE


class FakeTransport:
    """Stand-in for the WhatsApp send API; records what was sent."""

    def __init__(self) -> None:
        self.sent: List[Message] = []

    def deliver(self, message: Message) -> Message:
        self.sent.append(message)
        return message

    def count(self) -> int:
        return len(self.sent)


class MessageSender:
    """Orchestrates a reply through window policy and conversation state."""

    def __init__(self, store: ConversationStore, transport: Optional[FakeTransport] = None) -> None:
        self.store = store
        self.transport = transport if transport is not None else FakeTransport()

    def _window_for(self, contact: Contact, now: datetime) -> WindowStatus:
        reference = self.store.reference_for(contact)
        return evaluate_window(reference, now)

    def can_send_free_form(self, contact: Contact, now: datetime) -> bool:
        """Whether a free-form reply is allowed for ``contact`` at ``now``."""

        return self._window_for(contact, now).is_open

    def send_reply(self, reply: IntendedReply, now: datetime) -> SendResult:
        """Send ``reply`` the right way for the current window state.

        Outbound replies are recorded back into the store so the running
        conversation summary stays current.
        """

        contact = reply.contact
        window = self._window_for(contact, now)

        if reply.prefer_template and reply.template_name:
            return self._send_template(reply, window, now)

        if window.is_open:
            message = outbound(
                contact,
                when=now,
                kind=MessageKind.FREE_FORM,
                text=reply.text,
            )
            self.transport.deliver(message)
            self.store.record(message)
            return SendResult(
                decision=Decision.SENT_FREE_FORM,
                contact=contact,
                window=window,
                message=message,
            )

        # Window closed: a template is required.
        if reply.template_name:
            return self._send_template(reply, window, now)

        return SendResult(
            decision=Decision.REJECTED,
            contact=contact,
            window=window,
            reason="window closed and no template available",
        )

    def _send_template(self, reply: IntendedReply, window: WindowStatus, now: datetime) -> SendResult:
        message = outbound(
            reply.contact,
            when=now,
            kind=MessageKind.TEMPLATE,
            text=reply.template_name,
        )
        self.transport.deliver(message)
        self.store.record(message)
        return SendResult(
            decision=Decision.SENT_TEMPLATE,
            contact=reply.contact,
            window=window,
            message=message,
        )

    def deliveries(self) -> List[Message]:
        return list(self.transport.sent)

